import sys

def solve():
    MOD = 998244353
    data = sys.stdin.read().split()
    N = int(data[0]); M = int(data[1])
    A = [int(x) - 1 for x in data[2:2+N]]

    state = [0] * N
    cycle_id = [-1] * N
    num_cycles = 0

    for start in range(N):
        if state[start] != 0:
            continue
        path = []
        v = start
        while state[v] == 0:
            state[v] = 1
            path.append(v)
            v = A[v]
        if state[v] == 1:
            idx = path.index(v)
            cid = num_cycles
            num_cycles += 1
            for i in range(idx, len(path)):
                cycle_id[path[i]] = cid
            for u in path:
                state[u] = 2
        else:
            for u in path:
                state[u] = 2

    def node_of(i):
        if cycle_id[i] >= 0:
            return N + cycle_id[i]
        return i

    total_nodes = N + num_cycles
    children = [[] for _ in range(total_nodes)]

    for i in range(N):
        if cycle_id[i] >= 0:
            continue
        p = node_of(A[i])
        children[p].append(i)

    roots = [N + cid for cid in range(num_cycles)]
    order = []
    for r in roots:
        stack = [r]
        while stack:
            v = stack.pop()
            order.append(v)
            for c in children[v]:
                stack.append(c)
    order.reverse()

    f = [None] * total_nodes

    for v in order:
        fv = [1] * (M + 1)
        fv[0] = 0
        for c in children[v]:
            fc = f[c]
            s = 0
            Fc = [0] * (M + 1)
            for k in range(1, M + 1):
                s = (s + fc[k]) % MOD
                Fc[k] = s
            for k in range(1, M + 1):
                fv[k] = fv[k] * Fc[k] % MOD
            f[c] = None
        f[v] = fv

    ans = 1
    for r in roots:
        s = 0
        for k in range(1, M + 1):
            s = (s + f[r][k]) % MOD
        ans = ans * s % MOD

    print(ans)

